import {useEffect,useRef,useState} from 'react'; import {Link,NavLink,Route,Routes,useNavigate,useParams} from 'react-router-dom'; import {useMutation,useQuery,useQueryClient} from '@tanstack/react-query'; import {API,request,saveToken} from './api'; import {MapContainer,TileLayer,Marker,Popup} from 'react-leaflet'; import 'leaflet/dist/leaflet.css'; import L from 'leaflet';
type Incident={id:string;incident_code:string;incident_type:string;description:string;status:string;urgency:string;verification_status:string;latitude:number|null;longitude:number|null;address:string;postcode:string;reporter_name:string;reporter_phone:string;source:string;created_at:string;updated_at:string;verified_at?:string|null;location_source:string;ai_confidence:number;ai_summary:string;ai_missing:string[];assigned_unit_id?:string;assigned_unit_code?:string;ai_confidence_band?:string;ai_incident_type?:string;ai_detected_type?:string;ai_assessment_details?:any;assigned_unit?:any;available_units?:any[];nearest_unit_suggestion?:any;triage_recommendation?:any;demo?:boolean};
const label=(s:string)=>s?.replaceAll('_',' ')||'—';
